#include <bits/stdc++.h>
using namespace std;

static void appendUtf8(string &s, unsigned cp) {
    if (cp < 0x80) s += char(cp);
    else if (cp < 0x800) s += char(0xC0 | cp >> 6), s += char(0x80 | (cp & 0x3F));
    else if (cp < 0x10000) s += char(0xE0 | cp >> 12), s += char(0x80 | (cp >> 6 & 0x3F)), s += char(0x80 | (cp & 0x3F));
    else s += char(0xF0 | cp >> 18), s += char(0x80 | (cp >> 12 & 0x3F)), s += char(0x80 | (cp >> 6 & 0x3F)), s += char(0x80 | (cp & 0x3F));
}

// Parses a JSON array of strings into UTF-8 byte strings.
static vector<string> parseArray(const string &in) {
    vector<string> items;
    size_t p = in.find('[') + 1;
    auto hex4 = [&](size_t at) { return (unsigned)stoul(in.substr(at, 4), nullptr, 16); };
    while (p < in.size() && in[p] != ']') {
        if (in[p] != '"') { p++; continue; }
        string s;
        p++;
        while (in[p] != '"') {
            if (in[p] != '\\') { s += in[p++]; continue; }
            char e = in[p + 1];
            p += 2;
            switch (e) {
                case 'b': s += '\b'; break;
                case 'f': s += '\f'; break;
                case 'n': s += '\n'; break;
                case 'r': s += '\r'; break;
                case 't': s += '\t'; break;
                case 'u': {
                    unsigned cp = hex4(p);
                    p += 4;
                    if (cp >= 0xD800 && cp < 0xDC00 && in.compare(p, 2, "\\u") == 0) {
                        unsigned lo = hex4(p + 2);
                        if (lo >= 0xDC00 && lo < 0xE000) cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00), p += 6;
                    }
                    appendUtf8(s, cp);
                    break;
                }
                default: s += e;  // \" \\ \/
            }
        }
        p++;
        items.push_back(s);
    }
    return items;
}

// Same escaping as Python json.dumps(..., ensure_ascii=False).
static void appendJson(string &out, const string &s) {
    static const char *hexd = "0123456789abcdef";
    out += '"';
    for (unsigned char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (c < 0x20) out += "\\u00", out += hexd[c >> 4], out += hexd[c & 15];
                else out += char(c);
        }
    }
    out += '"';
}

