import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    // Parses a JSON array of strings.
    static List<String> parseArray(String in) {
        List<String> items = new ArrayList<>();
        int p = in.indexOf('[') + 1;
        while (p < in.length() && in.charAt(p) != ']') {
            if (in.charAt(p) != '"') {
                p++;
                continue;
            }
            StringBuilder s = new StringBuilder();
            p++;
            while (in.charAt(p) != '"') {
                char c = in.charAt(p);
                if (c != '\\') {
                    s.append(c);
                    p++;
                    continue;
                }
                char e = in.charAt(p + 1);
                p += 2;
                switch (e) {
                    case 'b' -> s.append('\b');
                    case 'f' -> s.append('\f');
                    case 'n' -> s.append('\n');
                    case 'r' -> s.append('\r');
                    case 't' -> s.append('\t');
                    case 'u' -> {
                        // UTF-16 code units; surrogate pairs combine on their own.
                        s.append((char) Integer.parseInt(in.substring(p, p + 4), 16));
                        p += 4;
                    }
                    default -> s.append(e);
                }
            }
            p++;
            items.add(s.toString());
        }
        return items;
    }

    // Same escaping as Python json.dumps(..., ensure_ascii=False).
    static void appendJson(StringBuilder out, String s) {
        out.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\b' -> out.append("\\b");
                case '\f' -> out.append("\\f");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> {
                    if (c < 0x20) out.append(String.format("\\u%04x", (int) c));
                    else out.append(c);
                }
            }
        }
        out.append('"');
    }

    public static void main(String[] args) throws IOException {
        String in = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        long chapter = 0, section = 0;
        List<String> result = new ArrayList<>();
        for (String line : parseArray(in)) {
            if (line.startsWith("# ")) {
                chapter++;
                section = 0;
                result.add(chapter + ". " + line.substring(2));
            } else if (line.startsWith("## ")) {
                section++;
                result.add(chapter + "." + section + ". " + line.substring(3));
            }
        }
        StringBuilder out = new StringBuilder("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) out.append(", ");
            appendJson(out, result.get(i));
        }
        out.append("]\n");
        System.out.write(out.toString().getBytes(StandardCharsets.UTF_8));
        System.out.flush();
    }
}

package main

import (
	"bufio"
	"bytes"
	"io"
	"os"
	"strconv"
	"unicode/utf16"
	"unicode/utf8"
)

// parseArray parses a JSON array of strings into UTF-8 byte strings.
func parseArray(in []byte) [][]byte {
	var items [][]byte
	p := bytes.IndexByte(in, '[') + 1
	hex4 := func(at int) rune {
		v, _ := strconv.ParseUint(string(in[at:at+4]), 16, 32)
		return rune(v)
	}
	for p < len(in) && in[p] != ']' {
		if in[p] != '"' {
			p++
			continue
		}
		var s []byte
		p++
		for in[p] != '"' {
			if in[p] != '\\' {
				s = append(s, in[p])
				p++
				continue
			}
			e := in[p+1]
			p += 2
			switch e {
			case 'b':
				s = append(s, '\b')
			case 'f':
				s = append(s, '\f')
			case 'n':
				s = append(s, '\n')
			case 'r':
				s = append(s, '\r')
			case 't':
				s = append(s, '\t')
			case 'u':
				r := hex4(p)
				p += 4
				if utf16.IsSurrogate(r) && p+6 <= len(in) && in[p] == '\\' && in[p+1] == 'u' {
					if pair := utf16.DecodeRune(r, hex4(p+2)); pair != utf8.RuneError {
						r = pair
						p += 6
					}
				}
				s = utf8.AppendRune(s, r)
			default:
				s = append(s, e)
			}
		}
		p++
		items = append(items, s)
	}
	return items
}

// appendJSON escapes like Python json.dumps(..., ensure_ascii=False).
func appendJSON(out, s []byte) []byte {
	const hexd = "0123456789abcdef"
	out = append(out, '"')
	for _, c := range s {
		switch c {
		case '"':
			out = append(out, '\\', '"')
		case '\\':
			out = append(out, '\\', '\\')
		case '\b':
			out = append(out, '\\', 'b')
		case '\f':
			out = append(out, '\\', 'f')
		case '\n':
			out = append(out, '\\', 'n')
		case '\r':
			out = append(out, '\\', 'r')
		case '\t':
			out = append(out, '\\', 't')
		default:
			if c < 0x20 {
				out = append(out, '\\', 'u', '0', '0', hexd[c>>4], hexd[c&15])
			} else {
				out = append(out, c)
			}
		}
	}
	return append(out, '"')
}

func main() {
	in, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	chapter, section := 0, 0
	out := []byte{'['}
	first := true
	emit := func(prefix string, title []byte) {
		if !first {
			out = append(out, ',', ' ')
		}
		first = false
		out = appendJSON(out, append([]byte(prefix), title...))
	}
	for _, line := range parseArray(in) {
		if bytes.HasPrefix(line, []byte("# ")) {
			chapter++
			section = 0
			emit(strconv.Itoa(chapter)+". ", line[2:])
		} else if bytes.HasPrefix(line, []byte("## ")) {
			section++
			emit(strconv.Itoa(chapter)+"."+strconv.Itoa(section)+". ", line[3:])
		}
	}
	out = append(out, ']', '\n')
	os.Stdout.Write(out)
}
